def _get_section_option_value(parser, section, option):
    value = None
    funcs = [parser.getint, parser.getfloat, parser.getboolean, parser.get]
    for func in funcs:
        try:
            value = func(section, option)
            break
        except ValueError:
            continue
    return value

def decode(self, s, **kwargs):
    parser = self._get_parser(options=kwargs)
    parser.read_string(s)
    data = {}
    for option, _ in parser.defaults().items():
        data[option] = self._get_section_option_value(
            parser, default_section, option
        )
    for section in parser.sections():
        data[section] = {}
        for option, _ in parser.items(section):
            value = self._get_section_option_value(parser, section, option)
            if type_util.is_string(value):
                try:
                    value_decoded = self._json.decode(value)
                    value = value_decoded
                except JSONDecodeError:
                    pass
            data[section][option] = value
    return data

def encode(self, d, **kwargs):
    parser = self._get_parser(options=kwargs)
    for key, value in d.items():
        if not type_util.is_dict(value):
            parser.set(default_section, key, f"{value}")
            continue
        section = key
        parser.add_section(section)
        for option_key, option_value in value.items():
            if type_util.is_dict(option_value):
                parser.set(section, option_key, self._json.encode(option_value))
            else:
                parser.set(section, option_key, option_value)
    str_data = StringIO()
    parser.write(str_data)
    return str_data.getvalue()

def _get_parser(options):
    parser = ArgumentParser(**options)
    return parser

def decode(self, s=None, **kwargs):
    parser = self._get_parser(options=kwargs)

    keys_with_values = set(self.parse_keys(self.regex_keys_with_values, s))
    all_keys = Counter(self.parse_keys(self.regex_all_keys, s))
    for key in all_keys:
        count = all_keys[key]

        try:
            # If the key has a value...
            if key in keys_with_values:
                # and is defined once, collect the values
                if count == 1:
                    parser.add_argument(
                        key,
                        nargs="*",
                        # This puts multiple values in a list
                        # even though this won't always be wanted
                        # This is adressed after the dict is generated
                        required=False,
                    )
                # and is defined multiple times, collect the values
                else:
                    parser.add_argument(key, action="append", required=False)

            # If the key doesn't have a value...
            else:
                # and is defined once, store as bool
                if count <= 1:
                    parser.add_argument(key, action="store_true", required=False)
                # and is defined multiple times, count how many times
                else:
                    parser.add_argument(key, action="count", required=False)

        except ArgumentError as error:
            raise ValueError from error

    try:
        args = parser.parse_args(s.split())
    except BaseException as error:
        raise ValueError from error

    dict = vars(args)
    for key in dict:
        value = dict[key]
        # If only one value was written,
        # return that value instead of a list
        if type_util.is_list(value) and len(value) == 1:
            dict[key] = value[0]

    return dict

